from django.conf import settings
from django.db import migrations, models


ANOS_ATE_ESTAGIO = 2  # turma de 2024 estagia em 2026


def criar_turmas(apps, schema_editor):
    """Cada estágio ganha a turma do seu curso no ano em que começou (ingresso = 2 anos antes)."""
    Estagio = apps.get_model("core", "Estagio")
    Turma = apps.get_model("core", "Turma")
    cache = {}
    for e in Estagio.objects.all().only("id", "curso_id", "turma_texto", "data_inicio"):
        nome = " ".join((e.turma_texto or "").split())
        ano = e.data_inicio.year
        chave = (e.curso_id, nome.lower(), ano)
        if chave not in cache:
            cache[chave], _ = Turma.objects.get_or_create(
                curso_id=e.curso_id, nome=nome, ano_ingresso=ano - ANOS_ATE_ESTAGIO, defaults={"ano_estagio": ano},
            )
        Estagio.objects.filter(pk=e.pk).update(turma=cache[chave])


